import{_ as o,o as i,c as t,ag as a}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"SPEC: Open-Source Hardening & Repository Polish","description":"","frontmatter":{},"headers":[],"relativePath":"internal/SPEC-OPEN-SOURCE-HARDENING.md","filePath":"internal/SPEC-OPEN-SOURCE-HARDENING.md","lastUpdated":1777882948000}'),d={name:"internal/SPEC-OPEN-SOURCE-HARDENING.md"};function c(l,e,r,s,n,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="spec-open-source-hardening-repository-polish" tabindex="-1">SPEC: Open-Source Hardening &amp; Repository Polish <a class="header-anchor" href="#spec-open-source-hardening-repository-polish" aria-label="Permalink to &quot;SPEC: Open-Source Hardening &amp; Repository Polish&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Polish the RustChat repository so it presents as a serious, supported open-source product without overclaiming production readiness.</p><h2 id="non-destructive-rules" tabindex="-1">Non-Destructive Rules <a class="header-anchor" href="#non-destructive-rules" aria-label="Permalink to &quot;Non-Destructive Rules&quot;">​</a></h2><ul><li>Inspect before modifying; preserve existing project info</li><li>Improve weak files rather than blindly replacing</li><li>Do not delete existing source code, workflows, or docs</li><li>No fake badges; no secrets; placeholders clearly marked</li></ul><h2 id="audit-summary" tabindex="-1">Audit Summary <a class="header-anchor" href="#audit-summary" aria-label="Permalink to &quot;Audit Summary&quot;">​</a></h2><h3 id="already-strong" tabindex="-1">Already Strong <a class="header-anchor" href="#already-strong" aria-label="Permalink to &quot;Already Strong&quot;">​</a></h3><ul><li><code>README.md</code> — Comprehensive, honest about limitations</li><li><code>LICENSE</code> — Apache-2.0, present</li><li><code>CHANGELOG.md</code> — Keep a Changelog format, maintained</li><li><code>CODE_OF_CONDUCT.md</code> — Contributor Covenant, present</li><li><code>SECURITY.md</code> — Basic policy present</li><li><code>CONTRIBUTING.md</code> — Dev setup present, lacks DCO</li><li><code>.env.example</code> — Thorough</li><li><code>docker-compose.yml</code> — Production-oriented with health checks</li><li><code>.github/CODEOWNERS</code> — Detailed ownership</li><li><code>.github/pull_request_template.md</code> — Good template</li><li><code>.github/ISSUE_TEMPLATE/{bug,feature,refactor}.yml</code> — Present</li><li><code>.github/workflows/{ci,backend-ci,frontend-ci,release,docker-publish,compat,docs-ci-cd,frontend-dependency-review}.yml</code> — Present</li><li><code>docs/</code> — Well-structured VitePress docs site with admin, user, dev, architecture, operations, reference sections</li><li><code>scripts/</code> — Docker build, version bump, smoke tests present</li></ul><h3 id="missing-weak" tabindex="-1">Missing / Weak <a class="header-anchor" href="#missing-weak" aria-label="Permalink to &quot;Missing / Weak&quot;">​</a></h3><ul><li>Root: <code>ROADMAP.md</code>, <code>GOVERNANCE.md</code>, <code>SUPPORT.md</code>, <code>MAINTAINERS.md</code>, <code>DCO.md</code>, <code>VERSION</code></li><li>GitHub: <code>dco.yml</code>, <code>security.yml</code> (CodeQL + cargo audit), <code>nightly.yml</code>, <code>scorecard.yml</code></li><li>GitHub: issue templates for <code>documentation.md</code>, <code>security_hardening.md</code></li><li>GitHub: <code>dependabot.yml</code> missing cargo, github-actions, docker</li><li>GitHub: PR template missing DCO checkbox</li><li>Docs: <code>quickstart.md</code>, <code>deployment.md</code>, <code>development.md</code>, <code>architecture.md</code>, <code>security-model.md</code>, <code>release-process.md</code>, <code>github-protection.md</code>, <code>contributor-workflow.md</code></li><li>Scripts: <code>smoke-test.sh</code>, <code>check-release-ready.sh</code>, <code>dev-setup.sh</code>, <code>release-notes-check.sh</code></li><li>Cargo: no <code>deny.toml</code></li></ul><h2 id="implementation-plan" tabindex="-1">Implementation Plan <a class="header-anchor" href="#implementation-plan" aria-label="Permalink to &quot;Implementation Plan&quot;">​</a></h2><h3 id="phase-1-root-files" tabindex="-1">Phase 1: Root Files <a class="header-anchor" href="#phase-1-root-files" aria-label="Permalink to &quot;Phase 1: Root Files&quot;">​</a></h3><ol><li>Create <code>VERSION</code> (0.3.5)</li><li>Create <code>DCO.md</code> (Developer Certificate of Origin)</li><li>Create <code>GOVERNANCE.md</code> (lightweight governance model)</li><li>Create <code>SUPPORT.md</code> (support policy and channels)</li><li>Create <code>MAINTAINERS.md</code> (current maintainers)</li><li>Create <code>ROADMAP.md</code> (honest near-term roadmap)</li><li>Update <code>CONTRIBUTING.md</code> — add DCO sign-off section</li><li>Update <code>README.md</code> — add release channels, roadmap link, security reporting prominence</li><li>Update <code>SECURITY.md</code> — expand with supported versions, dependency process</li></ol><h3 id="phase-2-github-infrastructure" tabindex="-1">Phase 2: GitHub Infrastructure <a class="header-anchor" href="#phase-2-github-infrastructure" aria-label="Permalink to &quot;Phase 2: GitHub Infrastructure&quot;">​</a></h3><ol><li>Update <code>.github/pull_request_template.md</code> — add DCO checkbox</li><li>Create <code>.github/ISSUE_TEMPLATE/documentation.md</code></li><li>Create <code>.github/ISSUE_TEMPLATE/security_hardening.md</code></li><li>Update <code>.github/dependabot.yml</code> — add cargo, github-actions, docker</li><li>Create <code>.github/workflows/dco.yml</code></li><li>Create <code>.github/workflows/security.yml</code> (CodeQL Rust + cargo audit)</li><li>Create <code>.github/workflows/nightly.yml</code> (nightly builds, container tags)</li><li>Create <code>.github/workflows/scorecard.yml</code> (OpenSSF Scorecard)</li><li>Improve <code>.github/workflows/release.yml</code> — extract changelog, generate release notes</li><li>Improve unified <code>.github/workflows/ci.yml</code> — ensure frontend build/lint/test coverage</li></ol><h3 id="phase-3-documentation" tabindex="-1">Phase 3: Documentation <a class="header-anchor" href="#phase-3-documentation" aria-label="Permalink to &quot;Phase 3: Documentation&quot;">​</a></h3><p>Create targeted docs that complement the existing VitePress structure:</p><ol><li><code>docs/quickstart.md</code> — fastest path to running</li><li><code>docs/deployment.md</code> — evaluation vs production deployment</li><li><code>docs/development.md</code> — backend + frontend setup, tests, formatting</li><li><code>docs/architecture.md</code> — high-level summary linking to architecture/</li><li><code>docs/security-model.md</code> — auth assumptions, dependency process, vuln reporting, supported versions</li><li><code>docs/release-process.md</code> — nightly, RC, stable, container tags, changelog rules</li><li><code>docs/github-protection.md</code> — manual settings required (branch protection, rulesets, secret scanning)</li><li><code>docs/contributor-workflow.md</code> — fork, branch, sign-off, PR flow</li></ol><h3 id="phase-4-scripts-tooling" tabindex="-1">Phase 4: Scripts &amp; Tooling <a class="header-anchor" href="#phase-4-scripts-tooling" aria-label="Permalink to &quot;Phase 4: Scripts &amp; Tooling&quot;">​</a></h3><ol><li>Create <code>scripts/smoke-test.sh</code> — unified smoke test wrapper</li><li>Create <code>scripts/check-release-ready.sh</code> — pre-release validation</li><li>Create <code>scripts/dev-setup.sh</code> — one-command dev environment setup</li><li>Create <code>scripts/release-notes-check.sh</code> — validate CHANGELOG before release</li><li>Create <code>deny.toml</code> — minimal cargo-deny config for backend</li></ol><h3 id="phase-5-validation" tabindex="-1">Phase 5: Validation <a class="header-anchor" href="#phase-5-validation" aria-label="Permalink to &quot;Phase 5: Validation&quot;">​</a></h3><ol><li>Validate all new workflow YAML syntax</li><li>Run <code>cargo check</code> in backend</li><li>Run <code>cargo fmt --check</code> in backend</li><li>Run frontend <code>npm run build</code> if node_modules available</li><li>Document any build failures honestly</li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ul><li>[ ] Newcomer can understand what RustChat is from README</li><li>[ ] Contributor can set up dev env and sign commits from CONTRIBUTING.md</li><li>[ ] Maintainer can cut releases from docs/release-process.md</li><li>[ ] PRs are protected by backend checks, frontend checks, DCO, security checks</li><li>[ ] Manual GitHub settings are documented in docs/github-protection.md</li><li>[ ] Existing code still builds</li></ul>',24)])])}const p=o(d,[["render",c]]);export{m as __pageData,p as default};
